"""Shipping helpers: zone lookup, cost calculation, and oversize checks."""

_BASE_COST = {1: 5.0, 2: 12.0, 3: 25.0}


def shipping_zone(country_code):
    """Return 1 for US, 2 for CA or MX, and 3 for any other country code."""
    if country_code == "US":
        return 1
    if country_code in ("CA", "MX"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    """Return base + 1.5 * weight_kg, rounded to 2 decimals, for the given zone."""
    base = _BASE_COST[zone]
    return round(base + 1.5 * weight_kg, 2)


def is_oversize(l, w, h):
    """True if any dimension exceeds 150 or the total l + w + h exceeds 360."""
    return l > 150 or w > 150 or h > 150 or (l + w + h) > 360

"""Pricing helpers: bulk discounts, line totals, and SKU parsing."""
import re

_SKU_RE = re.compile(r"^([A-Z]{2,4})/(\d{4})/([A-Za-z])$")


def bulk_discount(qty):
    """Return the discount rate for an integer quantity."""
    if qty >= 100:
        return 0.15
    if qty >= 20:
        return 0.05
    return 0.0


def line_total(unit_price, qty):
    """Return unit_price * qty * (1 - bulk_discount(qty)), rounded to 2 decimals."""
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    """Parse a SKU of the form CAT/1234/X into a dict.

    Raises ValueError if the string does not match the expected form.
    """
    if not isinstance(s, str):
        raise ValueError(f"invalid SKU: {s!r}")
    m = _SKU_RE.match(s)
    if not m:
        raise ValueError(f"invalid SKU: {s!r}")
    category, number, variant = m.group(1), m.group(2), m.group(3)
    return {"category": category, "number": int(number), "variant": variant}

